import {pose,gear} from './model.mjs';
export function scene(sun=110,mode='ring'){
 const p=pose(sun,mode);
 const bolts=[0,60,120,180,240,300].map(a=>`<circle cx="${267*Math.cos(a*Math.PI/180)}" cy="${267*Math.sin(a*Math.PI/180)}" r="3" fill="#a9bab8"/>`).join('');
 const ticks=Array.from({length:72},(_,i)=>`<path transform="rotate(${i*5})" d="M 0 -306 v ${i%6===0?12:4}" stroke="#819b99" opacity=".6"/>`).join('');
 const planet=p.centers.map((c,i)=>`<g transform="translate(${c.x} ${c.y})"><g transform="rotate(${p.planet+15})"><path d="${gear(12,60)}" fill="#92aaa4" stroke="#284b47" stroke-width="1.5"/><circle r="42" fill="#a8bbb4" stroke="#53766e"/><path d="M 0 -35 V -49" stroke="#f7f0dc" stroke-width="4"/></g><circle r="11" fill="#173d3a" stroke="#e6d8b8" stroke-width="3"/><text x="0" y="4" text-anchor="middle" font-family="monospace" font-size="10" fill="#f5efdf">${i+1}</text></g>`).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 720" role="img" aria-label="行星齿轮，中央太阳轮驱动三个行星轮，外侧为齿圈"><defs><radialGradient id="bg"><stop stop-color="#244f48"/><stop offset="1" stop-color="#102e2c"/></radialGradient></defs><rect width="720" height="720" rx="24" fill="url(#bg)"/><g transform="translate(360 360)">${ticks}<circle r="290" fill="none" stroke="#61817a" stroke-width=".5"/><g transform="rotate(${p.ring})"><path d="M 285 0 A285 285 0 1 0 -285 0 A285 285 0 1 0 285 0 Z ${gear(48,240,true)}" fill="#42665f" fill-rule="evenodd" stroke="#9caf9e" stroke-width="1.2"/>${bolts}<path d="M0 -254v-23" stroke="#f4db9b" stroke-width="4"/></g><circle r="180" fill="none" stroke="#91a49a" stroke-dasharray="2 6" opacity=".5"/><g stroke="#e8d5a7" stroke-width="18" stroke-linecap="round" opacity=".65">${p.centers.map(c=>`<path d="M0 0L${c.x} ${c.y}"/>`).join('')}</g><g transform="rotate(${p.sun})"><path d="${gear(24,120)}" fill="#d87948" stroke="#f1bf7b" stroke-width="1.5"/><circle r="92" fill="#c5683d" stroke="#f0b577"/><circle r="74" fill="none" stroke="#e49b63" stroke-dasharray="2 8"/><path d="M0 -58V-108" stroke="#ffedb1" stroke-width="5" stroke-linecap="round"/></g>${planet}<g stroke="#e8d5a7" stroke-width="8" stroke-linecap="round" opacity=".65">${p.centers.map(c=>`<path d="M0 0L${c.x} ${c.y}"/>`).join('')}</g><circle r="31" fill="#e9d8b3" stroke="#ffefc8" stroke-width="2"/><circle r="15" fill="#244b45"/><path d="M-6 0h12" stroke="#abc0b0" stroke-width="2"/></g><text x="28" y="38" fill="#c2cec0" font-size="11" font-family="monospace" letter-spacing="2">KINEMATIC STUDY / 01</text><text x="28" y="691" fill="#a9bcb1" font-size="11" font-family="monospace">24 : 12 : 48</text><text x="692" y="691" text-anchor="end" fill="#a9bcb1" font-size="11" font-family="monospace">${mode==='ring'?'RING LOCKED':'CARRIER LOCKED'}</text></svg>`;
}
